def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    table = {4: 1, 3: 2, 2: 3}
    for o in objects(g, bg=bg):
        col = table.get(o["size"], o["colour"])
        for (y, x) in o["cells"]:
            out[y, x] = col
        emit(out, f"Object of size {o['size']} at bbox {o['box']} recoloured to {col} (size 4->1, 3->2, 2->3).")
    emit(out, "All objects recoloured by size; final grid.")
    return out
